import hashlib

def compute_file_hash(file_path):
    with open(file_path, ""rb"") as f:
        chunk_size = 1024 * 1024
        md5 = hashlib.md5()
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            md5.update(chunk)
        return md5.hexdigest()
