import random

def merge_lists(list_size, min_value, max_value, array_size):
    # Allocate memory for the linked list and initialize each node with a random integer within the given range
    nodes = []
    for i in range(list_size):
        nodes.append(random.randint(min_value, max_value))

    # Print the values of the nodes in the linked list
    print(""Linked List:"")
    for node in nodes:
        print(node)

    # Allocate memory for the hash table and update its capacity if necessary
    hash_table = {}
    if len(nodes) > array_size:
        array_size = len(nodes)
    for i in range(array_size):
        hash_table[i] = None

    # Populate both data structures by adding elements from the linked list into corresponding slots within the hash table
    for node in nodes:
        index = random.randint(0, array_size - 1)
        while hash_table[index] is not None:
            index = (index + 1) % array_size
        hash_table[index] = node

    return hash_table
```
