import urllib.parse
import logging

def parse_url(url):
    try:
        parsed = urllib.parse.urlparse(url)
        scheme = parsed.scheme
        domain = parsed.netloc
        port = parsed.port or 80
        path = parsed.path
        return (scheme, domain, port, path)
    except ValueError as e:
        logging.error(""Invalid URL: {}"".format(url))
        return (-1, ""INVALID_URL"", -1, """")
    except Exception as e:
        logging.error(""Unknown error while parsing URL: {}"".format(url))
        return (-1, ""UNKNOWN_ERROR"", -1, """")
```
