import hashlib

def get_file_md5(filename):
    with open(filename, 'rb') as f:
        hasher = hashlib.md5()
        while True:
            chunk = f.read(4096)
            if not chunk:
                break
            hasher.update(chunk)
        return hasher.hexdigest()
