class FibonacciCalculator:
    def calculateNthFibonacci(self, n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            return self.calculateNthFibonacci(n-1) + self.calculateNthFibonacci(n-2)

    def validateSequence(self, input_list):
        for i in range(len(input_list)):
            if not isinstance(input_list[i], int) or input_list[i] < 0:
                raise ValueError(""Invalid input"")

        expected_output = [0, 1]
        for i in range(2, len(input_list)):
            expected_output.append(expected_output[-2] + expected_output[-1])

        if input_list != expected_output:
            raise ValueError(""Invalid output"")

    def optimizeSequence(self, input_list):
        memo = {}

        for i in range(len(input_list)):
