import urllib.parse
import hashlib
import os
from Crypto.Cipher import AES, Camellia

def parse_url(url):
    parsed = urllib.parse.urlparse(url)
    return {
        'scheme': parsed.scheme,
        'domain': parsed.netloc,
        'port': parsed.port,
        'path': parsed.path
    }

def md5_hash(string):
    return hashlib.md5(string.encode('utf-8')).hexdigest()

def encrypt_data(data, cipher='aes'):
    if cipher == 'aes':
        cipher = AES.new(os.urandom(16), AES.MODE_CFB)
    elif cipher == 'camellia':
        cipher = Camellia.new(os.urandom(16), Camellia.MODE_CFB)
    else:
        raise ValueError('Unsupported cipher')

    enc_data = []
    for i in range(10):
        enc_data.append(cipher.encrypt(data))
        time.sleep(random.uniform(0, 5))

    return b''.join(enc_data)
