class BinaryTreeManager:
    def __init__(self, max_depth=3):
        self.root = None
        self.max_depth = max_depth

    def add_book(self, book):
        if not self.root:
            self.root = Node(book.title, book.author)
        else:
            for child in self.root.child_nodes:
                if len(child.child_nodes) < self.max_depth - 1:
                    child.add_node(book)
                    break
            else:
                # Handle as needed, e.g., create new child nodes or move books to appropriate locations in the tree structure
                pass

    def get_data(self, position):
        if self.root and position == 0:
            return self.root.title, self.root.author
        elif self.root and len(self.root.child_nodes) > position - 1:
            return self.root.child_nodes[position - 1].get_data(position)
        else:
            # Handle as needed, e.g., create new child nodes or move books to appropriate locations in the tree structure
            pass

def main():
