    book1 = Book(""Title 1"", ""Author 1"", ""Genre 1"")
    book2 = Book(""Title 2"", ""Author 2"", ""Genre 2"")
    book3 = Book(""Title 3"", ""Author 3"", ""Genre 3"")

    # Create a BinaryTreeManager object with a maximum depth of 3
    tree = BinaryTreeManager(max_depth=3)

    # Add the three books to the binary tree
    tree.add_book(book1)
    tree.add_book(book2)
    tree.add_book(book3)

    # Print the data at each position in the tree
    print(tree.get_data(0))
    print(tree.get_data(1))
    print(tree.get_data(2))
    print(tree.get_data(3))

if __name__ == ""__main__"":
