[PYTHON]
def complex_key_value_search(json_string, keys, case_sensitive=False):
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError as e:
        raise ValueError(""Invalid JSON input"") from e

    result = {}

    def _search(dct, keys_list):
        if not isinstance(dct, dict) and not isinstance(dct, list):
            raise TypeError(""Invalid key type"")

        if isinstance(dct, list):
            for item in dct:
                _search(item, keys_list)

            return

        for key in dct.keys():
            if isinstance(key, str) or (not case_sensitive and isinstance(key, bytes)):
                if key in keys_list:
                    result[key] = dct[key]
                    keys_list.remove(key)

            elif isinstance(key, dict) or isinstance(key, list):
                _search(dct[key], keys_list)

            elif not case_sensitive and isinstance(key.encode(), bytes):
                for k in dct.keys():
                    if k.encode() == key.encode():
                        result[k] = dct[k]
                        keys_list.remove(k)

    _search(data, list(keys))

    return result
[/PYTHON]
