import os
from collections import deque

class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def add(self, value):
        node = Node(value)
        if self.head is None:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node

    def remove(self, value):
        current = self.head
        while current is not None:
            if current.value == value:
                previous.next = current.next
                return True
            previous = current
            current = current.next
        return False

    def search(self, value):
        current = self.head
        while current is not None:
            if current.value == value:
                return current
            current = current.next
        return None

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class HashTable:
    def __init__(self):
        self.buckets = {}

    def add(self, key, value):
        self.buckets[key] = value

    def remove(self, key):
        del self.buckets[key]

    def search(self, key):
        return self.buckets.get(key)

class Stack:
    def __init__(self):
        self.items = deque()

    def push(self, item):
        self.items.appendleft(item)

    def pop(self):
        return self.items.popleft()

