1,"Create a Python script that processes command line arguments to manage a library catalog. The script should accept options like --add to add a new book, --remove to delete a book, and --search to look up books by title or author. If no action is specified, the script should display usage instructions. When adding or removing books, the script should read from and write to a JSON file containing the catalog data.",121,,"['
import json
import sys

def main():
    args = sys.argv[1:]
    if len(args) == 0:
        print(""Usage: python library_catalog.py [--add|--remove|--search]"")
        return
    action = args[0]
    if action not in [""--add"", ""--remove"", ""--search""]:
        print(""Invalid action. Please specify one of --add, --remove or --search."")
        return
    if action == ""--add"":
        add_book()
    elif action == ""--remove"":
        remove_book()
    else:
        search_books()

def add_book():
    title = input(""Enter the book title: "")
    author = input(""Enter the author name: "")
    catalog.append({""title"": title, ""author"": author})
    with open(""catalog.json"", ""w"") as f:
        json.dump(catalog, f)

def remove_book():
    title = input(""Enter the book title to remove: "")
    for i in range(len(catalog)):
        if catalog[i][""title""] == title:
            del catalog[i]
            with open(""catalog.json"", ""w"") as f:
                json.dump(catalog, f)
            print(f""Book {title} removed from the catalog."")
            return
    print(f""No book with title {title} found in the catalog."")

def search_books():
    query = input(""Enter the title or author to search for: "")
    results = []
    for book in catalog:
        if query in book[""title""] or query in book[""author""]:
            results.append(book)
    if len(results) == 0:
        print(f""No books found with title or author containing {query}."")
    else:
        print(""Books found:"")
        for result in results:
            print(f""Title: {result['title']}, Author: {result['author']}"")

if __name__ == ""__main__"":
    main()
