0,"Write a Python program to calculate the total size (in bytes) of all `.txt` and `.docx` files within a specified input directory. The program should utilize the `argparse` module for accepting command-line arguments, including the input directory path, output file path, and verbosity flag. It will traverse the directory, measure the size of each `.txt` and `.docx` file using `get_file_size`, aggregate these sizes, and output the total size along with detailed information about each file to an output file. The main function should parse arguments, validate if the input directory exists, execute the size measurement operation, sort the file details for readability, and write them into the output file.",121,,"['```python
import argparse
import os

def get_file_size(path):
    return os.stat(path).st_size

def measure_file_sizes(input_dir):
    txt_sizes = []
    docx_sizes = []

    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.endswith('.txt'):
                txt_sizes.append(get_file_size(os.path.join(root, file)))
            elif file.endswith('.docx'):
                docx_sizes.append(get_file_size(os.path.join(root, file)))

    total_txt_size = sum(txt_sizes)
    total_docx_size = sum(docx_sizes)

    return (total_txt_size, total_docx_size)

def write_file_details(output_file, file_details):
    with open(output_file, 'w') as f:
        for detail in file_details:
            f.write('{}\n'.format(detail))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('input_dir', type=str, help='Input directory path')
    parser.add_argument('output_file', type=str, help='Output file path')
    parser.add_argument('--verbose', action='store_true', help='Enable verbose mode')
    args = parser.parse_args()

    if not os.path.exists(args.input_dir):
        print(""Input directory does not exist!"")
        return

    file_details = []
    total_txt_size, total_docx_size = measure_file_sizes(args.input_dir)

    if args.verbose:
        print('Total text files size: {} bytes'.format(total_txt_size))
        print('Total docx files size: {} bytes'.format(total_docx_size))

    for root, dirs, files in os.walk(args.input_dir):
        for file in files:
            if file.endswith('.txt'):
                detail = '{} - {} bytes'.format(os.path.join(root, file), get_file_size(os.path.join(root, file)))
                file_details.append(detail)
            elif file.endswith('.docx'):
                detail = '{} - {} bytes'.format(os.path.join(root, file), get_file_size(os.path.join(root, file)))
                file_details.append(detail)

    if args.verbose:
        print('Writing file details to output file...')

    write_file_details(args.output_file, file_details)

if __name__ == '__main__':
    main()
```']",0,[0],[],True,0,0,0,

