    def calculateSHA1(self, input_string):
        if input_string is None:
            return ""Input string cannot be None""
        else:
            import hashlib
            sha1_obj = hashlib.sha1()
            sha1_obj.update(input_string.encode())
            return sha1_obj.hexdigest()

    def checkFunctionality(self):
        test_cases = [
