            (""abcdefghijklmnopqrstuvwxyz"", ""e2bc87c2c5a8eb1a7cd8f4515437fc2f4d2f8fbf""),
        ]
        for test_case in test_cases:
            input_string, expected_result = test_case
            result = self.calculateSHA1(input_string)
            if result != expected_result:
                print(""Error! Expected"", expected_result, ""but got"", result)
        else:
            print(""All tests passed!"")
