0,"Develop a script that automates the process of creating and managing user accounts for a web application. The script should generate unique usernames, securely hash passwords, and assign roles based on predefined rules. It should also validate input parameters to ensure each generated account adheres to the system's security policies before being added to a list for easy access and management. Additionally, implement functionality to reset passwords securely and update user roles as needed. This solution aims to streamline user account creation while maintaining high levels of security through robust password hashing and role-based access control mechanisms.",680,,"['import hashlib
from random import choice
from string import digits, ascii_letters

class UserAccountManager:
    def __init__(self):
        self.users = []
        self.roles = [""admin"", ""user""]
        self.username_length = 10
        self.password_length = 20

    def generate_unique_username(self, length=None):
        if length is None:
            length = self.username_length
        return ''.join(choice(digits + ascii_letters) for _ in range(length))

    def hash_password(self, password):
        salt = b'saltysalt\0\0\0\0'
        iterations = 100000
        dklen = 32
        return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations, dklen)

    def assign_role(self, user):
        role = choice(self.roles)
        self.users[user][""role""] = role
        return role

    def validate_inputs(self, username, password):
        if len(username) > self.username_length:
            raise ValueError(""Username length exceeds maximum allowed length"")
        if len(password) < self.password_length:
            raise ValueError(""Password length does not meet minimum required length"")

    def add_user(self, username, password):
        self.validate_inputs(username, password)
        user = {
            ""username"": username,
            ""password"": self.hash_password(password),
            ""role"": self.assign_role(username)
        }
        self.users.append(user)
        return user

    def update_user(self, username, new_password=None, new_role=None):
        if new_password is not None:
            user[""password""] = self.hash_password(new_password)
        if new_role is not None:
            user[""role""] = new_role
        return user

    def reset_password(self, username, new_password):
        user = self.users[username]
        user[""password""] = self.hash_password(new_password)
        return user

    def get_user(self, username):
        return self.users[username]

    def list_users(self):
        return self.users
