import Foundation

struct NetworkRequestOperation {
    let method: String
    let url: URL
    let headers: [String: String]
    let timeout: TimeInterval
}

func generateNetworkRequestOperations(count: Int, customHeaders: [String: String] = [:]) -> [NetworkRequestOperation] {
    // Validate input parameters
    guard count >= 0 else {
        return []
    }

    var operations: [NetworkRequestOperation] = []

    for i in 0..<count {
        let method = ""GET""
        let url = URL(string: ""https://example.com/path/\(i)"")!
        let headers = customHeaders.merging([""User-Agent"": ""My App""]) { (_, new) -> String in new }
        let timeout = 60.0

        // Validate each object before adding it to the list
        guard method == ""GET"" || method == ""POST"" else {
            continue
        }

        guard url != nil else {
            continue
        }

        guard headers[""User-Agent""] != nil else {
            continue
        }

        operations.append(NetworkRequestOperation(method: method, url: url, headers: headers, timeout: timeout))
    }

    return operations
}
```
