import shutil
from random import randint

def get_file_line_count(file_path):
    try:
        with open(file_path, 'r') as file:
            return sum(1 for line in file)
    except FileNotFoundError:
        print(f""File not found: {file_path}"")
        return 0

def parse_args():
    parser = argparse.ArgumentParser(description=""Aggregate line count across all files in a directory, and optionally create a backup."")
    parser.add_argument('-i', '--input', required=True, help=""Path to the input directory."")
    parser.add_argument('-o', '--output', required=True, help=""Path to the output file."")
    parser.add_argument('-v', '--verbose', action='store_true', help=""Enable verbose output."")
    parser.add_argument('--backup-dir', default='backup', help=""Path to the backup directory. Default is 'backup'."")
    parser.add_argument('--max-backup-keep', type=int, default=5, help=""Maximum number of backups to keep. Default is 5."")

    return parser.parse_args()

def create_backup(src_path, dst_path):
    try:
        shutil.copy2(src_path, dst_path)
        print(f""Backup created: {dst_path}"")
    except Exception as e:
        print(f""Failed to create backup: {e}"")

def main():
    args = parse_args()

    if not os.path.exists(args.input):
        print(""Input directory does not exist!"")
        exit(1)

    total_line_count = 0
    file_info_list = []

    if os.path.isdir(args.input):
        backup_dir = args.backup_dir
        max_backups = args.max_backup_keep

        if not os.path.exists(backup_dir):
            os.makedirs(backup_dir)

        for root_dir, _, files in os.walk(args.input):
            for file in files:
                if not (file.endswith('.py') or file.endswith('.php')):
                    continue

                full_file_path = os.path.join(root_dir, file)
                lines_in_file = get_file_line_count(full_file_path)

                total_line_count += lines_in_file
                file_info_list.append((full_file_path, lines_in_file))

                # Create a backup of each processed file before removing it from original location
                src_backup_name = f""{os.path.splitext(file)[0]}_{randint(100000000, 999999999)}""
                dst_backup_path = os.path.join(backup_dir, src_backup_name)
                create_backup(full_file_path, dst_backup_path)

    # Sort the file information list by line count in descending order
    sorted_file_info_list = sorted(file_info_list, key=lambda x: x[1], reverse=True)

    with open(args.output, 'w') as output_file:
        for file_path, lines_in_file in sorted_file_info_list[:max_backups]:
            output_file.write(f""{lines_in_file} {file_path}\n"")

    if args.verbose:
        print(f""Total line count: {total_line_count}"")

if __name__ == ""__main__"":
    main()']",0,[0],[],True,0,0,0,

