import numpy as np

# Function for matrix multiplication
def mat_mult(A, B):
    return A @ B

# Function for matrix inversion
def inv(A):
    # Check if the matrix is invertible
    if np.linalg.det(A) == 0:
        raise ValueError(""Matrix is not invertible"")

    # Compute the inverse of the matrix using numpy's linag.inv() function
    return np.linalg.inv(A)

# Function for solving systems of linear equations
def solve_sys(A, b):
    # Check if the matrix is invertible
    if np.linalg.det(A) == 0:
        raise ValueError(""Matrix is not invertible"")

    # Solve the system of equations using numpy's linag.solve() function
    return np.linalg.solve(A, b)
