import random
import string
from typing import List, Tuple

def generate_random_records(db_conn: object, num_records: int) -> None:
    # Create a table named 'records' if it doesn't already exist
    db_conn.execute(""CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, name VARCHAR(255), age INT, email VARCHAR(255), phone_number CHAR(10), address TEXT)"")

    # Define the data types and lambda functions for each field
    fields = [
        (""id"", ""INTEGER PRIMARY KEY""),
        (""name"", ""VARCHAR(255)""),
        (""age"", ""INT""),
        (""email"", ""VARCHAR(255)""),
        (""phone_number"", ""CHAR(10)""),
        (""address"", ""TEXT"")
    ]

    # Generate a random value for each field using the lambda function
    for i in range(num_records):
        record = {}
        for field, data_type in fields:
            if data_type == ""INTEGER"":
                record[field] = random.randint(1, 100)
            elif data_type == ""VARCHAR(255)"":
                record[field] = """".join(random.choice(string.ascii_letters + string.digits) for _ in range(10))
            elif data_type == ""INT"":
                record[field] = random.randint(1, 100)
            elif data_type == ""CHAR(10)"":
                record[field] = str(random.randint(100000000, 999999999))
            elif data_type == ""TEXT"":
                record[field] = "" "".join(random.choice(string.ascii_letters + string.digits) for _ in range(10))
        db_conn.execute(""INSERT INTO records (id, name, age, email, phone_number, address) VALUES (:id, :name, :age, :email, :phone_number, :address)"", record)
