def paginate(func):
  def wrapper(*args, **kwargs):
    # Check if the request has a next page parameter
    if ""next_page"" in kwargs:
      # Use the next page parameter to retrieve the next set of results
      next_results = func(*args, **kwargs)
      # Return a list of results and the next page URL
      return [next_results], {""next_url"": ""http://example.com/api/v1/users?page=2""}
    else:
      # No next page specified, retrieve all results
      results = func(*args, **kwargs)
      # Return a list of results and an empty next page URL
