        return ()

    # Initialize variables to keep track of the current maximum product and its indices
    max_product = 1
    start = 0
    end = 0

    # Iterate through the list, updating the maximum product and its indices as we go
    for i in range(len(lst)):
        prod = 1
        for j in range(i, len(lst)):
            prod *= lst[j]
            if prod > max_product:
                max_product = prod
                start = i
                end = j

    # Return the subarray with the highest product
    return (start, end)
