class FileSystemManager:
    def __init__(self):
        self.file_system = {}

    def initialize(self):
        pass

    def push(self, value):
        if value not in self.file_system:
            self.file_system[value] = []
        return True

    def pop(self, value):
        if value in self.file_system:
            del self.file_system[value]
            return True
        return False

def main():
