2,"Create a Python script that analyzes a CSV file containing temperature and humidity data for multiple days. The script should parse each line, extract the temperature and humidity values, calculate the standard deviation for each day's data, and then construct a WeatherDataSummary object. Each object should include the day's date, average temperature, average humidity, minimum temperature, maximum temperature, minimum humidity, maximum humidity, and the standard deviation of both temperature and humidity. The script should open the ""weather_data.csv"" file, read it line by line using comma as a delimiter to split fields. If a day contains at least two data points (temperature and humidity), it will compute their respective averages and standard deviations. Finally, it will print out all WeatherDataSummary objects with detailed information for each day's analysis.",680,,"[""```
import csv
from statistics import stdev
from datetime import date

class WeatherDataSummary:
    def __init__(self, day, avg_temp, avg_humidity, min_temp, max_temp, min_humidity, max_humidity, std_dev):
        self.day = day
        self.avg_temp = avg_temp
        self.avg_humidity = avg_humidity
        self.min_temp = min_temp
        self.max_temp = max_temp
        self.min_humidity = min_humidity
        self.max_humidity = max_humidity
        self.std_dev = std_dev

def read_csv(filename):
    with open(filename, 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        data = []
        for row in reader:
            if len(row) != 3:
                continue
            day = date.fromisoformat(row[0])
            temp = float(row[1])
            humidity = float(row[2])
            data.append((day, temp, humidity))
    return data

def compute_stats(data):
    stats = {}
    for day, temp, humidity in data:
        if day not in stats:
            stats[day] = {
                'temp': [],
                'humidity': []
            }
        stats[day]['temp'].append(temp)
        stats[day]['humidity'].append(humidity)
    for day, values in stats.items():
        try:
            avg_temp = sum(values['temp']) / len(values['temp'])
            std_dev_temp = stdev(values['temp'])
            min_temp = min(values['temp'])
            max_temp = max(values['temp'])
            avg_humidity = sum(values['humidity']) / len(values['humidity'])
            std_dev_humidity = stdev(values['humidity'])
            min_humidity = min(values['humidity'])
            max_humidity = max(values['humidity'])
        except ZeroDivisionError:
            continue
        else:
            yield WeatherDataSummary(day, avg_temp, avg_humidity, min_temp, max_temp, min_humidity, max_humidity, std_dev)

if __name__ == '__main__':
    data = read_csv('weather_data.csv')
    for summary in compute_stats(data):
        print(summary)
